      "basis": "按分批到货检验、材质证明与测试报告整理工作量估算"
    },
    {
      "item": "保修响应与备件支持",
      "amount": 420000,
      "basis": "按保修期内响应窗口与备件储备作暂估，外部支持是否接受保修与质量文档要求待核实"
    },
    {
      "item": "物流、清关与现场交付协调",
      "amount": 510000,
      "basis": "按项目所在地交付与清关协调工作量暂估，物流伙伴尚未确认"
